--- @return number|nil cooldownMs, number|nil maxCharges, number|nil rechargeMs
function lib.Get(spellID)
    local v = D[spellID]
    if not v then return nil end
    if type(v) == "table" then return nil, v[1], v[2] end
    return v
end
